def get_digits(n):
    return [int(d) for d in str(n)]

def remove_digit(n, i):
    s = str(n)
    return int(s[:i] + s[i+1:])

memo = {}

def is_good(m):
    if m in memo:
        return memo[m]

    # Base case: single-digit numbers
    if 0 < m <= 9:
        memo[m] = True
        return True

    # Constraint check: must have distinct nonzero digits
    s_m = str(m)
    if len(s_m) > 0:
        digits = set(int(d) for d in s_m)
        if len(digits) != len(s_m) or 0 in digits:
            # If the input m violates the problem constraints (though unlikely if called correctly)
            # we treat it as not good if it's not a single digit based on constraints.
            pass

    # Recursive check
    for i in range(len(str(m))):
        d_prime = remove_digit(m, i)

        # d_prime must be a divisor of m AND d_prime must be a good number
        if m % d_prime == 0:
            if is_good(d_prime):
                memo[m] = True
                return True

    memo[m] = False
    return False

# Function to test candidates starting from a high value
def find_largest_good_number(start_val, stop_val):
    print("Starting search...")
    for m in range(start_val, stop_val - 1, -1):
        s_m = str(m)
        digits = set(int(d) for d in s_m)

        # Check distinct nonzero digits constraint
        if len(digits) != len(s_m) or 0 in digits:
            continue

        if is_good(m):
            return m
    return None

