def is_good(m):
    if m < 10:
        return True

    s = str(m)
    digits = [int(d) for d in s]

    for i in range(len(digits)):
        # Remove digit i
        m_prime_str = "".join(str(d) for j, d in enumerate(digits) if j != i)
        if not m_prime_str:
            continue
        m_prime = int(m_prime_str)

        if m % m_prime == 0:
            if is_good(m_prime):
                return True
    return False

